/**
 * source for the `backend.js` orchestrator that ships inside every
 * platform-bundle. it's a small CommonJS script with no dependencies beyond
 * node built-ins; treat the string as the actual deployable file.
 *
 * keep this in its own module so platform.ts stays focused on assembly logic.
 */
export declare const backendOrchestratorSource = "#!/usr/bin/env node\n/* eslint-disable */\n// generated by @bitdev/platforms.platform \u2014 do not edit by hand.\nconst { spawn } = require('node:child_process');\nconst { readFileSync } = require('node:fs');\nconst { join } = require('node:path');\nconst http = require('node:http');\n\nconst { statSync, existsSync, createReadStream } = require('node:fs');\nconst path = require('node:path');\n\nconst ROOT = __dirname;\nconst manifest = JSON.parse(readFileSync(join(ROOT, 'manifest.json'), 'utf8'));\nconst argv = process.argv.slice(2);\n\nconst MIME = {\n  '.html':'text/html','.js':'application/javascript','.css':'text/css',\n  '.json':'application/json','.png':'image/png','.jpg':'image/jpeg',\n  '.svg':'image/svg+xml','.ico':'image/x-icon','.woff2':'font/woff2',\n  '.woff':'font/woff','.ttf':'font/ttf','.map':'application/json',\n};\n\nfunction serveFrontend(dir, port) {\n  const srv = http.createServer((req, res) => {\n    const url = req.url.split('?')[0];\n    let fp = join(dir, url === '/' ? 'index.html' : url);\n    if (!existsSync(fp) || statSync(fp).isDirectory()) fp = join(dir, 'index.html');\n    if (!existsSync(fp)) { res.writeHead(404); res.end(); return; }\n    res.writeHead(200, { 'Content-Type': MIME[path.extname(fp)] || 'application/octet-stream' });\n    createReadStream(fp).pipe(res);\n  });\n  srv.listen(port, () => console.log('frontend serving at: http://localhost:' + port));\n  return srv;\n}\n\nfunction runModule(entry) {\n  const mod = require(join(ROOT, entry));\n  const app = mod.default || mod;\n  if (app && typeof app.run === 'function') {\n    const port = parseInt(process.env.PORT || '3000', 10);\n    const services = [];\n    const SUFFIX = '__PLATFORM_SERVICE_URL';\n    for (const [k, v] of Object.entries(process.env)) {\n      if (!k.endsWith(SUFFIX) || k.length === SUFFIX.length) continue;\n      if (typeof v !== 'string' || !/^https?:\\/\\//i.test(v)) continue;\n      services.push({\n        appName: k.slice(0, -SUFFIX.length).toLowerCase().replace(/_/g, '-'),\n        url: v,\n      });\n    }\n    Promise.resolve(app.run({ port, services })).catch(function (e) {\n      console.error(e);\n      process.exit(1);\n    });\n  } else if (typeof app === 'function') {\n    app();\n  }\n}\n\nif (argv.includes('--list')) {\n  if (manifest.gateway && manifest.gateway.entry) console.log('gateway');\n  for (const name of Object.keys(manifest.services || {})) console.log(name);\n  if (manifest.frontend && manifest.frontend.dir) console.log(manifest.frontend.name || 'frontend');\n  process.exit(0);\n}\n\nif (argv.includes('--help') || argv.includes('-h')) {\n  console.log('usage: node backend.cjs [<service>|--list] [--no-frontend] [--no-proxy]');\n  console.log('  no args        start gateway + all services + frontend + public proxy');\n  console.log('  <name>         start only that service (or \"gateway\" or \"frontend\")');\n  console.log('  --list         list available service names');\n  console.log('  --no-frontend  skip frontend in all-in-one mode');\n  console.log('  --no-proxy     skip public reverse-proxy in all-in-one mode');\n  console.log('');\n  console.log('env vars (all-in-one):');\n  console.log('  PORT           public reverse-proxy port (default 3000)');\n  console.log('  GATEWAY_PORT   internal gateway port    (default 4000)');\n  console.log('  FRONTEND_PORT  internal frontend port   (default 3001)');\n  console.log('  PORT_BASE      first service port - 1   (default 5000)');\n  process.exit(0);\n}\n\nfunction startFrontend(frontendPort, baseEnv) {\n  const fe = manifest.frontend;\n  if (!fe || !fe.dir) return null;\n  const feDir = join(ROOT, fe.dir);\n  if (!existsSync(feDir)) return null;\n  if (fe.entry) {\n    const absEntry = join(ROOT, fe.entry);\n    const boot = 'const m=require(' + JSON.stringify(absEntry) + ');' +\n      'const a=m.default||m;' +\n      'if(a&&typeof a.run===\"function\"){' +\n      'Promise.resolve(a.run({port:parseInt(process.env.PORT||\"3001\",10)}))' +\n      '.catch(function(e){console.error(e);process.exit(1)});' +\n      '}else if(typeof a===\"function\"){a();}';\n    const child = spawn(process.execPath, ['-e', boot], {\n      env: { ...(baseEnv || process.env), PORT: String(frontendPort) },\n      stdio: ['ignore', 'inherit', 'inherit'],\n    });\n    child.on('exit', (code) => {\n      console.error('[frontend] exit ' + code);\n    });\n    return child;\n  }\n  serveFrontend(feDir, frontendPort);\n  return null;\n}\n\n// Reverse-proxy that fronts the gateway + frontend on a single public port.\n// API paths route to the gateway, everything else to the frontend.\n//   /api/<rest>            -> gateway as /<rest>   (strip /api prefix)\n//   /graphql               -> gateway as /graphql\n//   /<service-name>/<rest> -> gateway as-is\n//   everything else        -> frontend\nfunction startProxy(publicPort, gatewayPort, frontendPort) {\n  const apiPrefixes = ['/graphql'].concat(\n    Object.keys(manifest.services || {}).map((n) => '/' + n)\n  );\n  const srv = http.createServer((req, res) => {\n    const p = req.url.split('?')[0];\n    const q = req.url.slice(p.length);\n    let upstreamPath = req.url;\n    let isApi = false;\n    if (p === '/api' || p.startsWith('/api/')) {\n      isApi = true;\n      upstreamPath = (p.slice(4) || '/') + q;\n    } else if (apiPrefixes.some((pre) => p === pre || p.startsWith(pre + '/'))) {\n      isApi = true;\n    }\n    const port = isApi ? gatewayPort : frontendPort;\n    const pr = http.request(\n      { host: '127.0.0.1', port: port, path: upstreamPath, method: req.method, headers: req.headers },\n      (pres) => { res.writeHead(pres.statusCode, pres.headers); pres.pipe(res); }\n    );\n    pr.on('error', (e) => { res.writeHead(502); res.end(e.message); });\n    req.pipe(pr);\n  });\n  srv.listen(publicPort, () => {\n    console.log('public proxy listening on http://localhost:' + publicPort);\n    console.log('  api -> http://localhost:' + gatewayPort);\n    console.log('  ui  -> http://localhost:' + frontendPort);\n  });\n  return srv;\n}\n\nconst positional = argv.find((a) => !a.startsWith('--'));\nif (positional) {\n  if (positional === 'gateway') {\n    if (!manifest.gateway || !manifest.gateway.entry) {\n      console.error('no gateway entry in manifest');\n      process.exit(2);\n    }\n    const urlVars = Object.keys(process.env).filter((k) => k.endsWith('__PLATFORM_SERVICE_URL'));\n    if (urlVars.length === 0) {\n      console.warn(\n        '[platform] warning: gateway started with no *__PLATFORM_SERVICE_URL env vars. ' +\n          'services will be unreachable until the deployer injects them.',\n      );\n    }\n    runModule(manifest.gateway.entry);\n  } else if (positional === 'frontend' || positional === manifest.frontend?.name) {\n    const fePort = parseInt(process.env.PORT || '3001', 10);\n    startFrontend(fePort);\n  } else {\n    const svc = (manifest.services || {})[positional];\n    if (!svc) {\n      console.error('unknown service: ' + positional);\n      console.error(\n        'available: ' +\n          ['gateway', 'frontend', ...Object.keys(manifest.services || {})].join(', '),\n      );\n      process.exit(2);\n    }\n    runModule(svc.entry);\n  }\n} else {\n  // all-in-one mode: spawn every service, then the gateway, then the frontend,\n  // and finally a reverse-proxy that exposes both api + ui on the public port.\n  const PORT_BASE = parseInt(process.env.PORT_BASE || '5000', 10);\n  const services = Object.entries(manifest.services || {}).map(([name, s], i) => ({\n    name,\n    entry: s.entry,\n    port: PORT_BASE + i + 1,\n  }));\n  const publicPort = parseInt(process.env.PORT || '3000', 10);\n  const gatewayPort = parseInt(process.env.GATEWAY_PORT || '4000', 10);\n  const frontendPort = parseInt(process.env.FRONTEND_PORT || '3001', 10);\n\n  const baseEnv = { ...process.env };\n  for (const s of services) {\n    const varName = s.name.toUpperCase().replace(/-/g, '_') + '__PLATFORM_SERVICE_URL';\n    baseEnv[varName] = 'http://localhost:' + s.port;\n  }\n  baseEnv.BACKEND_URL = 'http://localhost:' + gatewayPort;\n\n  function start(name, entry, port) {\n    const absEntry = join(ROOT, entry);\n    const boot = 'const m=require(' + JSON.stringify(absEntry) + ');' +\n      'const a=m.default||m;' +\n      'if(a&&typeof a.run===\"function\"){' +\n      'Promise.resolve(a.run({port:parseInt(process.env.PORT||\"3000\",10),services:[]}))' +\n      '.catch(function(e){console.error(e);process.exit(1)});' +\n      '}else if(typeof a===\"function\"){a();}';\n    const child = spawn(process.execPath, ['-e', boot], {\n      env: { ...baseEnv, PORT: String(port) },\n      stdio: ['ignore', 'inherit', 'inherit'],\n    });\n    child.on('exit', (code) => {\n      console.error('[' + name + '] exit ' + code);\n      process.exit(code || 1);\n    });\n    return child;\n  }\n\n  function waitFor(port, name) {\n    return new Promise(async (resolve, reject) => {\n      for (let i = 0; i < 30; i++) {\n        const ok = await new Promise((r) => {\n          const req = http.get('http://localhost:' + port, () => r(true));\n          req.on('error', () => r(false));\n        });\n        if (ok) return resolve();\n        await new Promise((r) => setTimeout(r, 1000));\n      }\n      reject(new Error(name + ' did not start on port ' + port + ' after 30s'));\n    });\n  }\n\n  (async () => {\n    const children = services.map((s) => start(s.name, s.entry, s.port));\n    for (const s of services) {\n      try {\n        await waitFor(s.port, s.name);\n      } catch (e) {\n        console.error(e.message);\n        children.forEach((c) => c.kill());\n        process.exit(1);\n      }\n    }\n    let gw;\n    if (manifest.gateway && manifest.gateway.entry) {\n      gw = start('gateway', manifest.gateway.entry, gatewayPort);\n    }\n    let feChild;\n    if (!argv.includes('--no-frontend') && manifest.frontend && manifest.frontend.dir) {\n      feChild = startFrontend(frontendPort, baseEnv);\n    }\n    let proxy;\n    if (!argv.includes('--no-proxy')) {\n      proxy = startProxy(publicPort, gatewayPort, frontendPort);\n    }\n    process.on('SIGINT', () => {\n      children.forEach((c) => c.kill('SIGINT'));\n      if (gw) gw.kill('SIGINT');\n      if (feChild) feChild.kill('SIGINT');\n      if (proxy) proxy.close();\n      process.exit(0);\n    });\n  })();\n}\n";
export type PlatformBundleManifest = {
    name: string;
    gateway: {
        name: string;
        entry: string;
    };
    frontend: {
        name: string;
        dir: string;
        entry?: string;
    };
    services: Record<string, {
        entry: string;
    }>;
};
